#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. This copy translates user-facing messages to Spanish as requested.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: shared UX, with Spanish messages requested by the user.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s etapas%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  Este asistente te guía por el navegador y guarda tus respuestas.\n' "$DIM"
  printf '  Puedes cancelar con Ctrl-C y repetirlo en el mismo destino:\n'
  printf '  conservará las respuestas guardadas.%s\n' "$RESET"
  pause "Pulsa Enter para comenzar."
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Etapa %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ abriendo%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "No se pudo abrir el navegador. Abre esta dirección: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Pulsa Enter para continuar}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [s/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Ss] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter conserva el valor actual]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter conserva el valor actual]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ guardado%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ configurado%s Secreto de GitHub %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("Secreto de GitHub $name (configúralo manualmente: gh secret set $name)")
  warn "Se omitió el secreto de GitHub $name: autentica gh y configúralo después"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ configurado%s Variable de GitHub %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("Variable de GitHub $name")
  warn "Se omitió la variable de GitHub $name: autentica gh y configúrala después"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Configuración completada%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "Se guardaron ${#WRITTEN_ENV[@]} valores en $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "Secretos de GitHub configurados: ${#WRITTEN_SECRET[@]}: ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "Queda pendiente:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Project helpers live below the immutable wizard library.
INSPECTION=""
SETUP_LOCK=""
fail() { warn "$1"; exit 1; }

capture() {
  local key="$1" prompt="$2" fallback="${3:-}" current
  current=$(_existing "$key" || true)
  say "$prompt [${current:-$fallback}]"
  ask "$key" "Valor (Enter conserva la propuesta):"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$fallback"
  [[ -n "${!key}" && "${!key}" != *$'\r'* && "${!key}" != *$'\n'* ]] || fail "Valor vacío o multilínea: $key"
  write_env "$key" "${!key}"
}

require_tool() {
  local name="$1" url="$2" instruction="$3"
  while ! command -v "$name" >/dev/null 2>&1; do
    open_url "$url"
    step "$instruction"
    pause "Instálalo en otra terminal y pulsa Enter. Ctrl-C cancela."
  done
}

setup() {
  # Loads the entrypoint inside the installation, where dependencies exist.
  # align_setup_entrypoint must have copied this checkout's scripts there.
  "$NODE_CLI" --experimental-strip-types "$FACTORY_DIR/scripts/setupFactory.ts" "$@"
}

# This shell is already the wizard contract. An existing Factory keeps its
# product code, so a repeat would otherwise run an older entrypoint whose
# prompts and checks no longer match. Copy only this checkout's wizard scripts.
align_setup_entrypoint() {
  [[ "$SOURCE_ROOT" == "$FACTORY_DIR" ]] && return 0
  cp -f "$SOURCE_ROOT/scripts/setupFactory.ts" "$FACTORY_DIR/scripts/setupFactory.ts"
  cp -f "$SOURCE_ROOT/scripts/testOpenCode.ts" "$FACTORY_DIR/scripts/testOpenCode.ts"
  rm -rf -- "$FACTORY_DIR/scripts/setup"
  cp -R "$SOURCE_ROOT/scripts/setup" "$FACTORY_DIR/scripts/"
}

suggest() {
  setup suggest "$ENV_FILE" "$INSPECTION" "$1"
}

cleanup_inspection() {
  if [[ -n "${INSPECTION:-}" ]]; then rm -rf -- "$INSPECTION"; fi
  if [[ -n "${SETUP_LOCK:-}" ]]; then rmdir -- "$SETUP_LOCK"; fi
}

run_wizard() {
  TOTAL_STAGES=8
  local SOURCE_ROOT INSTALL_ROOT FACTORY_DIR NODE_CLI VERCEL_CLI
  local key value actual expected
  local REPOSITORY BASE_BRANCH INSTRUCTIONS INSTALL_COMMAND CHECK_COMMANDS
  local E2E_ENABLED E2E_COMMAND E2E_CONFIG E2E_SERVER E2E_ORIGIN BUILD_DIRECTORY
  local VERCEL_SCOPE VERCEL_PROJECT VERCEL_PROJECT_ID VERCEL_TEAM_ID VERSION_PATH
  local PROVIDER MODEL REASONING_EFFORT OPENCODE_CLI INPUT_PRICE OUTPUT_PRICE CACHE_PRICE PORT
  if [[ "${1:-}" == "--help" ]]; then
    printf 'Uso: bash scripts/setup-factory.sh [DIRECTORIO_ABSOLUTO]\nSolo macOS. No arranca la Factory ni autoriza issues.\n'
    return
  fi
  [[ $# -le 1 ]] || fail "Solo se admite un directorio de destino."
  [[ "$(uname -s)" == "Darwin" ]] || fail "Este wizard solo admite macOS."
  [[ -t 0 ]] || fail "Ejecuta el wizard desde una terminal interactiva."
  SOURCE_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)
  umask 077
  banner "Puesta en marcha de App Foundry · macOS"

  stage "Destino de la instalación"
  say "Usa una carpeta dedicada. El código, los datos y la configuración estarán separados."
  if [[ -n "${1:-}" ]]; then INSTALL_ROOT=$1
  else ask INSTALL_ROOT "Ruta absoluta de destino, por ejemplo /Volumes/Disco/App Foundry:"
  fi
  [[ "$INSTALL_ROOT" == /* && "$INSTALL_ROOT" != *$'\n'* && "$INSTALL_ROOT" != *$'\r'* ]] || fail "Introduce una ruta absoluta de una sola línea."
  mkdir -p -- "$INSTALL_ROOT"
  INSTALL_ROOT=$(cd -- "$INSTALL_ROOT" && pwd -P)
  [[ "$INSTALL_ROOT" != / && "$INSTALL_ROOT" != "$HOME" ]] || fail "Usa una carpeta dedicada."
  FACTORY_DIR="$INSTALL_ROOT/factory"
  if [[ "$SOURCE_ROOT" != "$FACTORY_DIR" ]]; then
    case "$INSTALL_ROOT/" in "$SOURCE_ROOT/"*) fail "El destino debe estar fuera del código de la Factory.";; esac
    case "$SOURCE_ROOT/" in "$INSTALL_ROOT/"*) fail "El destino no puede contener este checkout.";; esac
  fi
  for key in factory data .setup.env .setup-config factory.local.json managed-project.json start-factory.sh; do
    [[ ! -L "$INSTALL_ROOT/$key" ]] || fail "No se admiten enlaces simbólicos en $key."
    if [[ -e "$INSTALL_ROOT/$key" && ! -f "$INSTALL_ROOT/.setup.env" ]]; then
      fail "El destino contiene $key ajeno al wizard. Elige una carpeta libre."
    fi
  done
  SETUP_LOCK="$INSTALL_ROOT/.setup.lock"
  mkdir -- "$SETUP_LOCK" || fail "Otro wizard usa este destino. Si se interrumpió, inspecciona .setup.lock antes de retirarlo."
  trap cleanup_inspection EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  ENV_FILE="$INSTALL_ROOT/.setup.env"
  if [[ -f "$ENV_FILE" ]]; then
    say "Se conservarán las respuestas anteriores como propuestas. Revisa también sus tarifas."
    confirm "¿Reconfigurar esta instalación? Se conservará una copia .previous" || exit 1
    chmod 600 "$ENV_FILE"
  fi
  write_env INSTALL_ROOT "$INSTALL_ROOT"

  stage "Requisitos e instalación de la Factory"
  require_tool git "https://developer.apple.com/xcode/resources/" "Instala las Command Line Tools con: xcode-select --install"
  require_tool node "https://nodejs.org/en/download" "Instala la versión de Node indicada en .node-version de la Factory."
  require_tool npm "https://docs.npmjs.com/downloading-and-installing-node-js-and-npm" "Instala npm junto con Node."
  expected=$(cat "$SOURCE_ROOT/.node-version")
  actual=$(node --version)
  [[ "$actual" == "v$expected" ]] || fail "Node requerido: $expected. Activo: $actual. Selecciona la versión y repite."
  expected=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1], 'utf8')).packageManager.split('@')[1]" "$SOURCE_ROOT/package.json")
  [[ "$(npm --version)" == "$expected" ]] || fail "Instala npm $expected con npm install --global npm@$expected y repite."
  NODE_CLI=$(command -v node)
  require_tool gh "https://cli.github.com/" "Instala GitHub CLI: brew install gh"
  require_tool vercel "https://vercel.com/docs/cli" "Instala Vercel CLI: npm install --global vercel"
  VERCEL_CLI=$(command -v vercel)
  write_env VERCEL_CLI "$VERCEL_CLI"
  if [[ ! -d "$FACTORY_DIR" ]]; then
    [[ -z "$(git -C "$SOURCE_ROOT" status --porcelain -- scripts/setup-factory.sh scripts/setupFactory.ts scripts/setup)" ]] || fail "El instalador tiene cambios sin commit. Usa una versión confirmada del wizard."
    say "Se instalará la versión HEAD confirmada. Los cambios sin commit del checkout no se copian."
    git -c core.hooksPath=/dev/null clone --no-hardlinks -- "$SOURCE_ROOT" "$FACTORY_DIR"
    git -C "$FACTORY_DIR" remote set-url origin https://github.com/rubenbp/app-foundry.git
  else
    [[ -f "$FACTORY_DIR/scripts/setupFactory.ts" ]] || fail "El directorio factory no contiene el instalador esperado."
    [[ "$(git -C "$FACTORY_DIR" remote get-url origin)" == "https://github.com/rubenbp/app-foundry.git" ]] || fail "El checkout instalado pertenece a otro repositorio."
  fi
  cd -- "$FACTORY_DIR"
  [[ ! -e "$INSTALL_ROOT/data/factory.lock" ]] || fail "Existe factory.lock. Detén la Factory e inspecciona el lock antes de reinstalar dependencias."
  HUSKY=0 npm ci
  node node_modules/@opencode/cli/postinstall.mjs
  align_setup_entrypoint
  setup stopped "$ENV_FILE"
  npm run typecheck
  npm run build

  stage "Cuenta y repositorio GitHub"
  if ! gh auth status --hostname github.com >/dev/null 2>&1; then
    open_url "https://github.com/login/device"
    step "La CLI mostrará un código. Inicia sesión y autoriza GitHub CLI."
    gh auth login --hostname github.com --git-protocol https --web
  fi
  capture REPOSITORY "Repositorio existente, formato propietario/nombre"
  [[ "$REPOSITORY" =~ ^[a-zA-Z0-9_-][a-zA-Z0-9_.-]*/[a-zA-Z0-9_-][a-zA-Z0-9_.-]*$ ]] || fail "Repositorio inválido."
  value=$(gh api "repos/$REPOSITORY" --jq .default_branch)
  capture BASE_BRANCH "Rama base" "$value"
  git check-ref-format --branch "$BASE_BRANCH" >/dev/null
  setup github "$ENV_FILE"
  INSPECTION=$(mktemp -d "$INSTALL_ROOT/.inspection.XXXXXX")
  git -c core.hooksPath=/dev/null -c 'credential.helper=!gh auth git-credential' \
    clone --depth 1 --single-branch --branch "$BASE_BRANCH" -- \
    "https://github.com/$REPOSITORY.git" "$INSPECTION"

  stage "Contrato de preparación y verificación del proyecto"
  while ! setup toolchain "$ENV_FILE" "$INSPECTION"; do
    pause "Instala las herramientas indicadas en otra terminal y pulsa Enter. Ctrl-C cancela."
  done
  say "Propuestas detectadas en la rama base. Los comandos se ejecutarán con entorno reducido."
  say "Separa elementos con |. No uses | dentro de un comando de esta lista."
  capture INSTRUCTIONS "Archivos de instrucciones relativos al repositorio" "$(suggest INSTRUCTIONS)"
  capture INSTALL_COMMAND "Comando de instalación de dependencias" "$(suggest INSTALL_COMMAND)"
  capture CHECK_COMMANDS "Comandos de verificación separados con |" "$(suggest CHECK_COMMANDS)"
  capture E2E_ENABLED "¿Configurar pruebas Playwright E2E? Escribe si o no" "$(suggest E2E_ENABLED)"
  if [[ "$E2E_ENABLED" == si ]]; then
    capture E2E_COMMAND "Comando E2E, incluido también en CHECK_COMMANDS" "$(suggest E2E_COMMAND)"
    capture E2E_CONFIG "Configuración Playwright relativa al repositorio" "$(suggest E2E_CONFIG)"
    capture BUILD_DIRECTORY "Directorio del build estático" "dist"
    capture E2E_ORIGIN "Origen HTTP local con puerto exclusivo" "http://127.0.0.1:4173"
    capture E2E_SERVER "Comando del servidor; ajusta puerto y directorio" "python3 -m http.server 4173 --bind 127.0.0.1 --directory $BUILD_DIRECTORY"
    if [[ "$E2E_SERVER" == python3\ * ]]; then
      require_tool python3 "https://www.python.org/downloads/macos/" "Instala Python 3 para el servidor estático elegido."
    fi
    say "Instala Chrome o el navegador Playwright que requieran las pruebas."
    say "Instala también el gestor de paquetes y la versión que declare el proyecto."
    say "La comprobación de base detectará dependencias o navegadores ausentes."
  fi
  pause "Revisa los comandos anteriores. Enter continúa."

  stage "Vercel y protección de GitHub"
  if ! "$VERCEL_CLI" whoami >/dev/null 2>&1; then
    open_url "https://vercel.com/login"
    "$VERCEL_CLI" login
  fi
  open_url "https://vercel.com/new"
  step "Selecciona el equipo e importa el repositorio, o abre su proyecto existente."
  step "Revisa framework, instalación, build y salida. El proyecto debe estar en la raíz del repositorio."
  step "En Settings, comprueba Git y la rama Production. Habilita System Environment Variables en Build and Deployment."
  warn "Importar un proyecto nuevo puede publicar el primer despliegue en producción."
  "$VERCEL_CLI" teams ls
  capture VERCEL_SCOPE "Slug del equipo elegido en Vercel"
  "$VERCEL_CLI" project ls --scope "$VERCEL_SCOPE"
  capture VERCEL_PROJECT "Nombre exacto del proyecto Vercel"
  # IDs are public, verified later against the API and Git integration.
  open_url "https://vercel.com/dashboard"
  step "En el proyecto, Settings → General: copia Project ID."
  capture VERCEL_PROJECT_ID "Project ID (prj_...)"
  step "En el equipo, Settings → General: copia Team ID."
  capture VERCEL_TEAM_ID "Team ID (team_...)"
  capture VERSION_PATH "Ruta del marcador JSON con sha del commit y dirty: false" "/version.json"
  setup project "$ENV_FILE"
  setup vercel "$ENV_FILE"
  open_url "https://github.com/$REPOSITORY/settings/branches"
  step "La rama base necesita una regla de protección clásica. Créala si no existe."
  step "Si tu plan no permite protegerla, resuelve ese requisito antes de continuar."
  pause "Enter cuando exista la regla."
  confirm "¿Añadir PR obligatoria y checks Vercel y Factory, con rama actualizada y administradores incluidos?" || exit 1
  setup protect "$ENV_FILE"
  say "La configuración remota está comprobada. Las previews se verificarán durante las Ejecuciones de la Factory."

  stage "Proveedor, modelo, esfuerzo y tarifas"
  capture PROVIDER "Proveedor: openai, google, anthropic u ollama" "openai"
  case "$PROVIDER" in openai|google|anthropic|ollama) ;; *) fail "Proveedor no admitido.";; esac
  value=$(command -v opencode || true)
  capture OPENCODE_CLI "Ruta absoluta de OpenCode V2 con auth export" "${value:-$FACTORY_DIR/node_modules/@opencode/cli/bin/opencode.exe}"
  [[ "$OPENCODE_CLI" == /* && -x "$OPENCODE_CLI" ]] || fail "OpenCode debe ser un ejecutable con ruta absoluta."
  case "$PROVIDER" in
    openai)
      open_url "https://opencode.ai/v2/docs/cli/providers"
      step "Usa OAuth de OpenAI en la CLI elegida. Puedes conservar una cuenta activa existente."
      if ! setup auth "$ENV_FILE" >/dev/null 2>&1; then
        say "No hay una cuenta OAuth compatible activa. Sigue el inicio de sesión de OpenCode."
        "$OPENCODE_CLI" auth login openai
      else
        "$OPENCODE_CLI" auth list
        if confirm "¿Cambiar la cuenta OpenAI activa?"; then "$OPENCODE_CLI" auth login openai; fi
      fi
      setup auth "$ENV_FILE"
      ;;
    google|anthropic)
      if [[ "$PROVIDER" == google ]]; then open_url "https://aistudio.google.com/api-keys"
      else open_url "https://console.anthropic.com/settings/keys"; fi
      step "Crea una API key si hace falta. Introdúcela solo en el prompt protegido de OpenCode."
      if ! setup auth "$ENV_FILE" >/dev/null 2>&1; then
        say "No hay una API key compatible activa. Introdúcela en OpenCode."
        "$OPENCODE_CLI" auth login "$PROVIDER" --method key
      else
        "$OPENCODE_CLI" auth list
        if confirm "¿Cambiar la cuenta activa de este proveedor?"; then "$OPENCODE_CLI" auth login "$PROVIDER" --method key; fi
      fi
      setup auth "$ENV_FILE"
      ;;
    ollama)
      require_tool ollama "https://docs.ollama.com/macos" "Instala y abre Ollama; descarga un modelo con herramientas mediante ollama pull MODELO."
      ollama list
      say "Ollama debe seguir activo en 127.0.0.1:11434. Este proveedor es experimental."
      ;;
  esac
  say "Catálogo de OpenCode. Usa el ID del modelo sin el prefijo proveedor/ ni #variante."
  "$OPENCODE_CLI" models --standalone
  capture MODEL "ID del modelo"
  # Show the available variants before asking, without sending a prompt.
  value=$(_existing REASONING_EFFORT || true)
  write_env REASONING_EFFORT "${value:-default}"
  say "Introduce las tres tarifas en USD por millón de tokens, con punto decimal."
  say "Son estimaciones. No se impone un presupuesto ni se acredita la factura. Usa 0 solo si es tu tarifa."
  capture INPUT_PRICE "Tarifa de entrada"
  capture OUTPUT_PRICE "Tarifa de salida, incluido razonamiento"
  capture CACHE_PRICE "Tarifa de lectura de caché"
  setup config "$ENV_FILE"
  setup catalog "$ENV_FILE"
  capture REASONING_EFFORT "Esfuerzo del catálogo anterior; default usa el predeterminado" default
  setup config "$ENV_FILE"
  setup model "$ENV_FILE"

  stage "Comprobación de la instalación"
  setup remote "$ENV_FILE"
  say "Se clonará y comprobará la base con los mismos adaptadores de la Factory."
  say "La instalación y las pruebas ejecutan código del repositorio seleccionado."
  confirm "¿Ejecutar instalación y verificaciones de este repositorio de confianza?" || exit 1
  setup base "$ENV_FILE"
  say "La prueba opcional siguiente envía un prompt corto al modelo y puede consumir cuota."
  if confirm "¿Probar también una respuesta real del modelo?"; then
    setup probe "$ENV_FILE"
  else
    say "Generación real sin comprobar. Se han validado credenciales, modelo, herramientas y esfuerzo sin inferencia."
  fi

  stage "Configuración final y arranque"
  capture PORT "Puerto del Dashboard" 4310
  setup finalize "$ENV_FILE"
  bash -n "$INSTALL_ROOT/start-factory.sh"
  finish
  say "Factory configurada. Para arrancar:"
  printf '  %q\n' "$INSTALL_ROOT/start-factory.sh"
  say "Dashboard: http://127.0.0.1:$PORT"
  say "El arranque recogerá los issues que ya tengan factory:ready. Ctrl-C detiene el proceso."
}

run_wizard "$@"; exit
